String repo = "package com.example.buildlab.repository;
public class ProduktRepository {
    private final List<Produkt> produkty = new ArrayList<>();
    public void zapisz(Produkt p) { produkty.add(p); }
    public List<Produkt> znajdzWszystkie() { return new ArrayList<>(produkty); }
    public Optional<Produkt> znajdzPoId(int id) { return produkty.stream().filter(p -> p.getId() == id).findFirst(); }
}";
Files.writeString(root.resolve(base + "/repository/ProduktRepository.java"), repo);

